const SQRT3 = Math.sqrt(3);
let n, s;
let fill_colors = ["#ffd919", "#ff4f19", "#4bd3e5"];
let stroke_colors = ["#2c2060"];
let backgroud_color = "#fffbe6";

function setup() {
  createCanvas(500, 500);
  // noLoop() removed for animation
  n = floor(random(2, 6));
  s = 100/n;
  strokeWeight(Math.max(0.1, Math.abs(random([s/6, s/4, s/2]))));
}

function draw() {
  if (random() < 1/2) {
    [stroke_colors, backgroud_color] = [[backgroud_color], stroke_colors[0]];
  }

  background(backgroud_color);
  translate(width/2, height/2);
  rotate(random([0, PI/6]));

	if (random() < 1/6) {
		fill_colors = [random(fill_colors)];
	}

  if (random() < 1/2) {
    make_dots();
    make_lines();
  } else {
    [fill_colors, stroke_colors] = [stroke_colors, fill_colors];
    make_lines();
    make_dots();
  }
}

function make_dots() {
  noStroke();
  for (let i = -n; i <= n; i++) {
    for (let j = -n; j <= n; j++) {
      if (abs(i+j) < n+1) {
        let x = (i*SQRT3 + j*SQRT3/2)*s;
        let y = (j*3/2)*s;
        fill(random(fill_colors));
        circle(x, y, s);
      }
    }
  }
}

function make_lines() {
  for (let i = -n+1; i <= n-1; i++) {
    for (let j = -n+1; j <= n-1; j++) {
      if (abs(i+j) < n) {
        var x = (i*SQRT3 + j*SQRT3/2)*s;
        var y = (j*3/2)*s;
        let m = random([1, 2, 3]);
        for (let k = 0; k < m; k++) {
          let i1 = i+random([-1, 0, +1]);
          let possibilities = [0];
          if (i1 != i-1) possibilities.push(-1);
          if (i1 != i+1) possibilities.push(1);
          let j1 = j+random(possibilities);
          if ((i1 != i) || (j1 != j)) {
            let x1 = (i1*SQRT3 + j1*SQRT3/2)*s;
            let y1 = (j1*3/2)*s;
            stroke(random(stroke_colors));
            line(x, y, x1, y1)
          }
        }
      }
    }
  }
}
